module dffrq_1x(CLK, D, RN, Q);
  input CLK, D, RN;
  output Q;
  wire CLK, D, RN;
  wire Q;
  wire next_state;
  reg  qi;
  assign #1 Q = qi;
  assign next_state = D;
  always 
    @(posedge CLK or negedge RN) 
      if (!RN) 
        qi <= 0;
      else qi <= next_state;
  initial 
    qi <= 1'b0;
endmodule

